"use strict";
import { useEffect, useState } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { useAccount, useConnectorClient, useChainId, usePublicClient, useWriteContract } from "wagmi";
import { encodeFunctionData } from "viem";
import { useEthersProvider } from "hooks/useEthersProvider";
import { getContractAddress, getContractAbi } from "uniswap/src/constants/contracts";
import { useEip5792Support } from "uniswap/src/features/transactions/swap/contexts/hooks/useEip5792Support";
export function useClaimRewards() {
  const { address } = useAccount();
  const chainId = useChainId();
  const provider = useEthersProvider({ chainId });
  const { data: client } = useConnectorClient();
  const publicClient = usePublicClient({ chainId });
  const { writeContractAsync } = useWriteContract();
  const queryClient = useQueryClient();
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [disableBatching, setDisableBatching] = useState(false);
  const supportsEip5792 = useEip5792Support(chainId);
  const voterAddress = getContractAddress(chainId, "Voter");
  const voterAbi = getContractAbi(chainId, "Voter");
  const voterAbiTyped = voterAbi;
  useEffect(() => {
    setDisableBatching(false);
  }, [client, chainId]);
  const claimRewards = async (params) => {
    if (!address || !provider || !voterAddress || !voterAbiTyped) {
      setError("Wallet not connected or contract not available");
      return { success: false, error: "Wallet not connected or contract not available" };
    }
    const { tokenId, bribeTokensByContract, feeTokensByContract } = params;
    setIsLoading(true);
    setError(null);
    try {
      console.log("\u{1F3AF} [CLAIM REWARDS] Starting claim process for tokenId:", tokenId);
      console.log("\u{1F3AF} [CLAIM REWARDS] Bribe contracts with tokens:", bribeTokensByContract);
      console.log("\u{1F3AF} [CLAIM REWARDS] Fee contracts with tokens:", feeTokensByContract);
      console.log("\u{1F3AF} [CLAIM REWARDS] EIP-5792 support:", supportsEip5792);
      const bribesArray = Object.keys(bribeTokensByContract);
      const bribeTokensArray = bribesArray.map((b) => bribeTokensByContract[b]);
      const feesArray = Object.keys(feeTokensByContract);
      const feeTokensArray = feesArray.map((f) => feeTokensByContract[f]);
      const hasBribes = bribesArray.length > 0;
      const hasFees = feesArray.length > 0;
      if (!hasBribes && !hasFees) {
        console.warn("[CLAIM REWARDS] No claimable rewards found");
        setIsLoading(false);
        const message = "No claimable rewards found";
        setError(message);
        return { success: false, error: message };
      }
      let transactionHash;
      const shouldBatch = supportsEip5792 && client && hasBribes && hasFees && !disableBatching;
      if (shouldBatch) {
        try {
          console.log("\u{1F48E} [CLAIM REWARDS] Using EIP-5792 batched transaction");
          const bribeCalldata = encodeFunctionData({
            abi: voterAbiTyped,
            functionName: "claimBribes",
            args: [bribesArray, bribeTokensArray, BigInt(tokenId)]
          });
          const feeCalldata = encodeFunctionData({
            abi: voterAbiTyped,
            functionName: "claimFees",
            args: [feesArray, feeTokensArray, BigInt(tokenId)]
          });
          const result = await client.request({
            method: "wallet_sendCalls",
            params: [{
              version: "2.0.0",
              chainId: `0x${chainId?.toString(16)}`,
              from: address,
              calls: [
                { to: voterAddress, data: bribeCalldata, value: "0x0" },
                { to: voterAddress, data: feeCalldata, value: "0x0" }
              ],
              atomicRequired: true
            }]
          });
          transactionHash = result?.id;
          console.log("\u{1F48E} [CLAIM REWARDS] Batched transaction submitted:", transactionHash);
        } catch (batchError) {
          console.warn("\u26A0\uFE0F [CLAIM REWARDS] Batched claim failed, falling back to sequential transactions:", batchError);
          setDisableBatching(true);
        }
      }
      if (!transactionHash) {
        console.log("\u26A1 [CLAIM REWARDS] Using regular transactions");
        const voterAddressHex = voterAddress;
        const tokenIdBigInt = BigInt(tokenId);
        const waitForReceipt = async (hash) => {
          if (publicClient) {
            await publicClient.waitForTransactionReceipt({ hash });
          } else if (provider) {
            await provider.waitForTransaction(hash);
          }
        };
        const withRetry = async (fn, maxAttempts = 3, delayMs = 1e3) => {
          for (let attempt = 1; attempt <= maxAttempts; attempt++) {
            try {
              return await fn();
            } catch (error2) {
              const isTransientError = error2?.message?.includes("Failed to initialize request");
              if (!isTransientError || attempt === maxAttempts) {
                throw error2;
              }
              console.warn(`\u26A0\uFE0F [CLAIM REWARDS] Attempt ${attempt} failed, retrying in ${delayMs}ms...`);
              await new Promise((resolve) => setTimeout(resolve, delayMs));
            }
          }
          throw new Error("Max retry attempts reached");
        };
        if (hasBribes) {
          const bribeArgs = bribesArray.map((b) => b);
          const bribeTokensArgs = bribeTokensArray.map(
            (tokens) => tokens.map((token) => token)
          );
          console.log("\u{1F4B0} [CLAIM BRIBES] Calling claimBribes with:", {
            bribes: bribeArgs,
            tokens: bribeTokensArgs,
            tokenId
          });
          const bribeHash = await withRetry(() => writeContractAsync({
            address: voterAddressHex,
            abi: voterAbiTyped,
            functionName: "claimBribes",
            args: [bribeArgs, bribeTokensArgs, tokenIdBigInt]
          }));
          console.log("\u{1F4B0} [CLAIM BRIBES] Transaction submitted:", bribeHash);
          await waitForReceipt(bribeHash);
          console.log("\u{1F4B0} [CLAIM BRIBES] Transaction confirmed");
          transactionHash = bribeHash;
        }
        if (hasFees) {
          const feeArgs = feesArray.map((f) => f);
          const feeTokensArgs = feeTokensArray.map(
            (tokens) => tokens.map((token) => token)
          );
          console.log("\u{1F4B0} [CLAIM FEES] Calling claimFees with:", {
            fees: feeArgs,
            tokens: feeTokensArgs,
            tokenId
          });
          const feeHash = await withRetry(() => writeContractAsync({
            address: voterAddressHex,
            abi: voterAbiTyped,
            functionName: "claimFees",
            args: [feeArgs, feeTokensArgs, tokenIdBigInt]
          }));
          console.log("\u{1F4B0} [CLAIM FEES] Transaction submitted:", feeHash);
          await waitForReceipt(feeHash);
          console.log("\u{1F4B0} [CLAIM FEES] Transaction confirmed");
          transactionHash = feeHash;
        }
      }
      console.log("\u2705 [CLAIM REWARDS] All claims completed successfully");
      try {
        const invalidatePromises = [];
        invalidatePromises.push(
          queryClient.invalidateQueries({ queryKey: ["voting-rewards-batch-onchain"], exact: false })
        );
        if (chainId !== void 0) {
          invalidatePromises.push(
            queryClient.invalidateQueries({ queryKey: ["voting-rewards-onchain", chainId], exact: false })
          );
        } else {
          invalidatePromises.push(queryClient.invalidateQueries({ queryKey: ["voting-rewards-onchain"], exact: false }));
        }
        await Promise.all(invalidatePromises);
      } catch (invalidateError) {
        console.warn("\u26A0\uFE0F [CLAIM REWARDS] Failed to invalidate voting reward queries", invalidateError);
      }
      setIsLoading(false);
      return { hash: transactionHash, success: true };
    } catch (err) {
      console.error("\u274C [CLAIM REWARDS] Error claiming rewards:", err);
      let errorMessage = "Failed to claim rewards";
      if (err?.message) {
        if (err.message.includes("user rejected")) {
          errorMessage = "Transaction was cancelled by user";
        } else if (err.message.includes("insufficient funds")) {
          errorMessage = "Insufficient funds for gas";
        } else if (err.message.includes("NotApprovedOrOwner")) {
          errorMessage = "You do not own this veABX lock";
        } else if (err.message.includes("execution reverted")) {
          errorMessage = "Transaction failed - please try again";
        } else {
          errorMessage = err.message;
        }
      }
      setError(errorMessage);
      setIsLoading(false);
      return { success: false, error: errorMessage };
    }
  };
  return {
    isLoading,
    error,
    claimRewards
  };
}
